text:
{
  "table": {
    "name": "income",
    "purpose": "Records of money received by a student organization (club): membership dues payments plus occasional fundraising, sponsorship, and school/Student Government appropriations, each row linked to the member who paid or secured the income. Dates fall in Sep–Oct 2019, consistent with a semester of club activity."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "income_id",
      "description": "Primary key; opaque record identifier (Airtable-style 'rec...' ID) uniquely identifying each income entry.",
      "status": "resolved"
    },
    "col_002": {
      "role": "date",
      "name": "income_date",
      "description": "Date the income was received, ranging 2019-09-01 to 2019-10-31.",
      "status": "resolved"
    },
    "col_003": {
      "role": "numeric",
      "name": "amount",
      "description": "Amount of income in dollars. 33 of 36 rows are $50 (the standard membership dues amount); the three non-dues entries are $200, $1000, and $3000 (fundraising, sponsorship, school appropriation).",
      "status": "resolved"
    },
    "col_004": {
      "role": "category",
      "name": "income_type",
      "description": "Source/category of the income: 'Dues' (33 rows), plus one each of 'Fundraising', 'Sponsorship', and 'School Appropration' (sic, likely 'School Appropriation').",
      "status": "resolved"
    },
    "col_005": {
      "role": "free_text",
      "name": "notes",
      "description": "Optional free-text note describing the income; present only for the three non-dues entries (e.g. 'Annual funding from Student Government.', 'Secured donations to help pay for speaker gifts.', 'Ad revenue for use on flyers used to advertise upcoming events.').",
      "status": "resolved"
    },
    "col_006": {
      "role": "foreign_key",
      "name": "member_id",
      "description": "Reference to member.col_001, the member associated with the income (the person who paid dues or secured the fundraising/sponsorship). Null for one row (likely the school appropriation, which has no individual member).",
      "status": "resolved"
    }
  }
}
